/**
 * Runtime configuration loaded from /config.json.
 * This file is generated by CDK at deploy time with the real
 * resource values (user pool ID, PKCE client ID, etc.).
 *
 * Falls back to import.meta.env VITE_* vars for local development.
 */

import type { RegistryData } from './workflowRegistry';

export interface AppConfig {
  cognitoUserPoolId: string;
  cognitoClientId: string;
  cognitoIdentityPoolId: string;
  cognitoDomain: string;
  awsRegion: string;
  runtimeArn: string;
  filesBucket: string;
  integrationConfigApiUrl?: string;
  /**
   * Base URL of the Project API (API Gateway) published by CDK at deploy time,
   * mirroring `integrationConfigApiUrl`. Consumed by `projectService.ts` for
   * shared, server-side project records (design Section 2d).
   */
  projectApiUrl?: string;
  ideUrl?: string;
  /**
   * Byte-identical copy of `workflow_registry.json` merged into `/config.json`
   * by CDK at deploy time (design Section 3a-iii). Consumed via
   * `getRegistry()` in `workflowRegistry.ts`.
   */
  workflowRegistry?: RegistryData;
}

let cachedConfig: AppConfig | null = null;

export async function loadConfig(): Promise<AppConfig> {
  if (cachedConfig) return cachedConfig;

  // Try loading runtime config from /config.json (deployed by CDK)
  try {
    const res = await fetch('/config.json');
    if (res.ok) {
      cachedConfig = await res.json();
      return cachedConfig!;
    }
  } catch {
    // Fall through to env vars
  }

  // Fallback to Vite env vars for local development
  cachedConfig = {
    cognitoUserPoolId: import.meta.env.VITE_COGNITO_USER_POOL_ID ?? '',
    cognitoClientId: import.meta.env.VITE_COGNITO_CLIENT_ID ?? '',
    cognitoIdentityPoolId: import.meta.env.VITE_COGNITO_IDENTITY_POOL_ID ?? '',
    cognitoDomain: import.meta.env.VITE_COGNITO_DOMAIN ?? '',
    awsRegion: import.meta.env.VITE_AWS_REGION ?? '',
    runtimeArn: import.meta.env.VITE_RUNTIME_ARN ?? '',
    filesBucket: import.meta.env.VITE_FILES_BUCKET ?? '',
  };
  return cachedConfig;
}

export function getConfig(): AppConfig {
  if (!cachedConfig) {
    throw new Error('Config not loaded. Call loadConfig() first.');
  }
  return cachedConfig;
}
